def tokenize(s: str):
    tokens = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            dot_cnt = 0
            while j < n and (s[j].isdigit() or s[j] == '.'):
                if s[j] == '.':
                    dot_cnt += 1
                j += 1
            num_str = s[i:j]
            if dot_cnt > 1:
                raise ValueError("Invalid number format")
            tokens.append(float(num_str))
            i = j
        else:
            raise ValueError(f"Unexpected character: {c}")
    return tokens


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self) -> float:
        result = self._expr()
        if self.pos != len(self.tokens):
            raise ValueError("Unexpected remaining tokens")
        return result

    def _expr(self) -> float:
        left = self._term()
        while self.peek() in ('+', '-'):
            op = self.advance()
            right = self._term()
            if op == '+':
                left += right
            else:
                left -= right
        return left

    def _term(self) -> float:
        left = self._factor()
        while self.peek() in ('*', '/'):
            op = self.advance()
            right = self._factor()
            if op == '*':
                left *= right
            else:
                left /= right  # float division
        return left

    def _factor(self) -> float:
        if self.peek() == '-':
            self.advance()
            return -self._factor()
        tok = self.advance()
        if isinstance(tok, float):
            return tok
        elif tok == '(':
            val = self._expr()
            if self.peek() != ')':
                raise ValueError("Missing ')'")
            self.advance()  # consume ')'
            return val
        else:
            raise ValueError(f"Unexpected token in factor: {tok}")
