def calc(expr):
    pos = 0
    n = len(expr)

    def skip_spaces():
        nonlocal pos
        while pos < n and expr[pos] == ' ':
            pos += 1

    def parse_expr():
        res = parse_term()
        while pos < n and expr[pos] in ('+', '-'):
            op = expr[pos]
            pos += 1
            skip_spaces()
            right = parse_term()
            res = res + right if op == '+' else res - right
        return res

    def parse_term():
        res = parse_factor()
        while pos < n and expr[pos] in ('*', '/'):
            op = expr[pos]
            pos += 1
            skip_spaces()
            right = parse_factor()
            res = res * right if op == '*' else res / right
        return res

    def parse_factor():
        if pos < n and expr[pos] in ('+', '-'):
            op = expr[pos]
            pos += 1
            skip_spaces()
            val = parse_factor()
            return val if op == '+' else -val
        return parse_atom()

    def parse_atom():
        nonlocal pos
        skip_spaces()
        if pos >= n:
            raise ValueError("Unexpected end of expression")
        if expr[pos] == '(':
            pos += 1
            res = parse_expr()
            skip_spaces()
            if pos < n and expr[pos] == ')':
                pos += 1
            else:
                raise ValueError("Missing closing parenthesis")
            return res
        start = pos
        while pos < n and (expr[pos].isdigit() or expr[pos] == '.'):
            pos += 1
        if pos == start:
            raise ValueError(f"Unexpected character at position {pos}: {expr[pos]}")
        return float(expr[start:pos])

    res = parse_expr()
    skip_spaces()
    if pos < n:
        raise ValueError(f"Unexpected character at position {pos}: {expr[pos]}")
    return res
