import re

def calc(expr):
    # Tokenize the expression into numbers, operators, and parentheses
    tokens = re.findall(r'\d*\.\d+|\d+|[+*/()-]', expr)
    pos = 0

    def parse_expression():
        nonlocal pos
        result = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        nonlocal pos
        result = parse_factor()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                result /= right
        return result

    def parse_factor():
        nonlocal pos
        if pos >= len(tokens):
            return 0.0

        token = tokens[pos]

        # Handle unary operators
        if token == '-':
            pos += 1
            return -parse_factor()
        elif token == '+':
            pos += 1
            return parse_factor()

        # Handle parentheses
        elif token == '(':
            pos += 1
            result = parse_expression()
            if pos < len(tokens) and tokens[pos] == ')':
                pos += 1
            return result

        # Handle numbers
        else:
            pos += 1
            return float(token)

    return parse_expression()
